{
  "claim": "A world model can be hardened against hidden causal cross-effects by enforcing that a legal action changes only the observation coordinates belonging to its verified actuator footprint while leaving all unrelated coordinates invariant.",
  "operation": {
    "name": "Causal Footprint Firewall",
    "attack": "Inject a low-rank cross-entity bridge into the latent transition, adding a term B_a z_x to an unrelated protected coordinate z_y for a legal action a, while fitting the decoder so ordinary rollout loss remains nearly unchanged.",
    "execution": "For each sampled state, enumerate legal action pairs with the same declared footprint and compare their predicted protected coordinates; use the environment transition as the reference oracle."
  },
  "invariant": "For every legal state-action pair (s,a), let F(a) be the verified set of observation coordinates causally writable by a and let j not belong to F(a); then the one-step intervention must satisfy M_j(s,do(a)) = s_j, and for any legal a' with the same footprint-relevant parameters, M_j(s,do(a)) = M_j(s,do(a')).",
  "carrier": {
    "model_interface": "Apply to the transition module of TD-MPC2, MBRL-Lib, WorldAgen, or Dreamer RSSM before decoding observations.",
    "task_schema": "MiniGrid supplies object, cell, pose, door, and inventory coordinates; ScienceWorld supplies object-property, container, room, and inventory coordinates.",
    "mask_source": "Build F(a) from the native symbolic transition or environment action specification rather than from the learned model."
  },
  "gate": {
    "duration": "2 minutes on one CPU process",
    "procedure": [
      "Collect 256 reachable states per task and enumerate legal action pairs.",
      "Run 2048 paired model interventions and matching environment transitions.",
      "Report protected-coordinate violation rate, maximum absolute protected-coordinate deviation, and task reward before and after the firewall.",
      "Fail if violation rate exceeds 1 percent, if any protected binary predicate flips without mask authorization, or if reward drops by more than 3 percent."
    ],
    "native_tasks": "Run first on one MiniGrid configuration and one ScienceWorld task using their native legal-action and symbolic-state APIs."
  },
  "repair": {
    "training": "Add a masked causal penalty on every protected coordinate and include paired legal-action counterexamples in each minibatch.",
    "projection": "At inference, overwrite unauthorized predicted coordinates with their current verified values: z'_j = z_j for j not in F(a).",
    "diagnostics": "Keep a per-action footprint ledger and reject any learned transition whose unauthorized edge persists after projection."
  },
  "novelty_risk": "Medium: the combination of action-effect masking, paired interventions, and latent cross-entity red teaming is plausibly distinct, but it may overlap with causal locality regularization and structured transition models; the contribution is strongest if the same oracle-derived firewall transfers unchanged from MiniGrid to ScienceWorld.",
  "decision": {
    "status": "pilot",
    "reason": "Executable with available environments and model hooks, testable under legal actions and truthful observations, and falsifiable within two minutes; do not claim security beyond the verified coordinate schema and one-step transition boundary."
  }
}
